CSS=open('base.css').read() if os.path.exists('base.css') else ''
def page(s):
    e=html.escape
    svc="".join(f'<li class="card reveal" style="--d:{i*80}ms"><span class="num">0{i+1}</span><h3>{e(a)}</h3><p>{e(b)}</p></li>' for i,(a,b) in enumerate(s["svc"]))
    gal="".join(f'<figure class="tile t{i} reveal" style="--d:{i*60}ms"><div class="tile-art"></div><figcaption>{c}</figcaption></figure>' for i,c in enumerate(["The space","Signature","Details","Community","Behind the scenes","Moments"]))
    return f'''<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{e(s["name"])} — {e(s["type"])}, {e(s["sub"])} (sample design)</title><meta name="description" content="Concept website for a fictional {e(s["type"].lower())} in {e(s["sub"])}. Sample design by BuildIT.">
<link rel="icon" href="data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 10 10%22><circle cx=%225%22 cy=%225%22 r=%225%22 fill=%22%23888%22/></svg>">
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family={s["fonts"]}&display=swap" rel="stylesheet">
<style>:root{{--bg:{s["bg"]};--fg:{s["fg"]};--ac:{s["ac"]};--ac2:{s["ac2"]};--card:{s["card"]};--hf:{s["hf"]};--bf:{s["bf"]};--r:{s["radius"]}}}</style><link rel="stylesheet" href="../assets/base.css"></head>
<body class="theme-{s["anim"]}"><a class="skip" href="#main">Skip to content</a>
<header class="nav"><a class="logo" href="#top">{e(s["name"])}</a><nav aria-label="Main"><a href="#services">Services</a><a href="#gallery">Gallery</a><a href="#about">About</a><a class="btn sm" href="#contact">{e(s["cta"])}</a></nav></header>
<main id="main"><section class="hero" id="top"><div class="hero-text"><p class="eyebrow">{e(s["type"])} · {e(s["sub"])}</p><h1 class="split">{e(s["tag"])}</h1><p class="lede">{e(s["lede"])}</p><div class="ctas"><a class="btn" href="#contact">{e(s["cta"])} <span aria-hidden="true">→</span></a><a class="btn ghost" href="#services">See services</a></div></div><div class="hero-art">{ART[s["anim"]]}</div></section>
<div class="marquee" aria-hidden="true"><div>{(" ✦ ".join([s["sub"],s["type"],s["hours"],"Northern Beaches"])+" ✦ ")*4}</div></div>
<section id="services" class="wrap"><h2 class="reveal">What we do</h2><ul class="cards">{svc}</ul></section>
<section id="gallery" class="wrap"><h2 class="reveal">Gallery</h2><div class="gallery">{gal}</div></section>
<section id="about" class="wrap about"><div class="reveal"><h2>About us</h2><p>{e(s["about"])}</p></div><dl class="facts reveal"><div><dt>Hours</dt><dd>{e(s["hours"])}</dd></div><div><dt>Where</dt><dd>{e(s["addr"])}</dd></div><div><dt>Call</dt><dd>{e(s["phone"])}</dd></div></dl></section>
<section id="contact" class="wrap contact reveal"><h2>{e(s["cta"])}</h2><p>Tell us what you need and we'll reply within one business day.</p>
<form onsubmit="event.preventDefault();this.querySelector('.ok').hidden=false"><label>Name<input name="n" required autocomplete="name"></label><label>Email<input type="email" name="e" required autocomplete="email"></label><label class="full">Message<textarea name="m" rows="3"></textarea></label><button class="btn" type="submit">Send enquiry</button><p class="ok" role="status" hidden>Thanks! This is a sample form — no message was sent.</p></form></section></main>
<footer class="wrap foot"><p>© 2026 {e(s["name"])} — a fictional business. Contact details are placeholders.</p><p><a href="../">← All BuildIT samples</a></p></footer>
<a class="badge" href="../">Sample design by <b>BuildIT</b></a><script src="../assets/site.js" defer></script></body></html>'''
for s in S:
    os.makedirs(s["slug"],exist_ok=True); open(f'{s["slug"]}/index.html','w').write(page(s))
cards="".join(f'<a class="ix" href="{s["slug"]}/" style="--c:{s["ac"]};--b:{s["bg"]};--f:{s["fg"]}"><span>{s["sub"]}</span><h2>{s["name"]}</h2><p>{s["type"]}</p></a>' for s in S)
open('index.html','w').write(f'''<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BuildIT — Sample websites for Northern Beaches businesses</title><link rel="icon" href="data:,"><style>body{{margin:0;font:16px/1.5 system-ui,sans-serif;background:#0d0d0d;color:#f5f5f5;padding:clamp(20px,5vw,64px)}}h1{{font-size:clamp(2rem,6vw,4rem);margin:0 0 .3em}}.g{{display:grid;gap:16px;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));margin-top:32px}}.ix{{display:block;padding:28px;border-radius:16px;background:var(--b);color:var(--f);text-decoration:none;border-bottom:6px solid var(--c);transition:transform .2s}}.ix:hover,.ix:focus-visible{{transform:translateY(-4px)}}.ix span{{font-size:.8rem;text-transform:uppercase;letter-spacing:.1em}}.ix h2{{margin:.3em 0}}a{{color:#9cf}}</style></head><body><h1>BuildIT sample sites</h1><p>Six concept websites for fictional Northern Beaches businesses, designed and built by BuildIT. All names, details and artwork are invented. <a href="CREDITS.md">Credits</a></p><div class="g">{cards}</div></body></html>''')
